uantity INTEGER NOT NULL CHECK(quantity > 0), PRIMARY KEY(user_id,prompt_id));\n+CREATE TABLE IF NOT EXISTS orders (id INTEGER PRIMARY KEY, user_id INTEGER NOT NULL REFERENCES users(id), status TEXT NOT NULL, subtotal_cents INTEGER NOT NULL, fee_cents INTEGER NOT NULL, total_cents INTEGER NOT NULL, created_at TEXT NOT NULL);\n+CREATE TABLE IF NOT EXISTS order_items (order_id INTEGER NOT NULL REFERENCES orders(id), prompt_id INTEGER NOT NULL REFERENCES prompts(id), creator_id INTEGER NOT NULL REFERENCES creators(id), quantity INTEGER NOT NULL, unit_price_cents INTEGER NOT NULL, PRIMARY KEY(order_id,prompt_id));\n+`\n+\n+export function createDatabase(filename = ':memory:'): PowerPromptDb {\n+  if (filename !== ':memory:') mkdirSync(dirname(filename), { recursive: true })\n+  const db = new Database(filename)\n+  db.pragma('journal_mode = WAL')\n+  db.exec(schema)\n+  seedDatabase(db)\n+  return db\n+}\n+\n+export function seedDatabase(db: PowerPromptDb) {\n+  const seed = db.transaction(() => {\n+    db.prepare('INSERT OR IGNORE INTO users VALUES (1, ?, ?)').run('guest@powerprompt.local', 'Guest curator')\n+    const addCreator = db.prepare('INSERT OR IGNORE INTO creators VALUES (?, ?, ?)')\n+    creators.forEach((row) => addCreator.run(...row))\n+    const categoryNames = [...new Set(prompts.map((row) => row[4] as string))]\n+    const addCategory = db.prepare('INSERT OR IGNORE INTO categories(id,name) VALUES (?,?)')\n+    categoryNames.forEach((name, index) => addCategory.run(index + 1, name))\n+    const addPrompt = db.prepare('INSERT OR IGNORE INTO prompts VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)')\n+    prompts.forEach((row) => addPrompt.run(...row))\n+    db.prepare('INSERT OR IGNORE INTO favorites VALUES (1,207)').run()\n+    db.prepare('INSERT OR IGNORE INTO favorites VALUES (1,31)').run()\n+    const addOrder = db.prepare('INSERT OR IGNORE INTO orders VALUES (?,?,?,?,?,?,?)')\n+    addOrder.run(1,1,'paid',2600,208,2808,'2026-07-04')\n+    addOrder.run(2,1,'paid',2400,192,2592,'2026-07-06')\n+    addOrder.run(3,1,'paid',3300,264,3564,'2026-07-08')\n+    const addItem = db.prepare('INSERT OR IGNORE INTO order_items VALUES (?,?,?,?,?)')\n+    addItem.run(1,207,1,1,900); addItem.run(1,160,1,1,1700)\n+    addItem.run(2,189,2,1,2400); addItem.run(3,301,2,1,1400); addItem.run(3,101,2,1,600); addItem.run(3,118,3,1,1000); addItem.run(3,31,2,1,0)\n+  })\n+  seed()\n+}\n+\n+let singleton: PowerPromptDb | undefined\n+export function getDatabase() {\n+  if (!singleton) singleton = createDatabase(join(process.cwd(), 'data', 'powerprompt.sqlite'))\n+  return singleton\n+}\n*** End Patch","command_type":"apply_patch","id":"runtime-18c107eee74c10dc.tool.command_run:call_Xb9IVqTcYjjXasN65fPcIZDF:2","provider_tool_call_id":"call_Xb9IVqTcYjjXasN65fPcIZDF","status":"completed","step":1,"type":"file_change"},"type":"item.completed"}
{"item":{"aggregated_output":"{\"changes\":[{\"kind\":\"add\",\"lines\":[\"import type { Analytics, CartSummary, CatalogInput, CatalogResult, Prompt } from '../contracts'\",\"import type { PowerPromptDb } from './db'\",\"\",\"const promptSelect = `p.id,p.slug,p.title,p.model,p.category,p.price_cents / 100.0 AS price,p.sold,p.views,p.rating,p.creator_id AS creatorId,c.name AS creator,p.aspect,p.description,p.image,p.featured,p.created_at AS createdAt,EXISTS(SELECT 1 FROM favorites f WHERE f.prompt_id=p.id AND f.user_id=@userId) AS favorite`\",\"\",\"export function getCatalog(db: PowerPromptDb, input: CatalogInput, userId = 1): CatalogResult {\",\"  const where = [`(@model = 'all' OR p.model = @model)`, `(@category = 'all' OR p.category = @category)`, `(@search = '' OR p.title LIKE '%' || @search || '%' OR p.description LIKE '%' || @search || '%')`, `(@favorites = 0 OR EXISTS(SELECT 1 FROM favorites fx WHERE fx.prompt_id=p.id AND fx.user_id=@userId))`, `(@free = 0 OR p.price_cents=0)`].join(' AND ')\",\"  const order = input.sort === 'newest' ? 'p.created_at DESC' : input.sort === 'popular' ? 'p.sold DESC' : 'p.featured DESC,p.sold DESC,p.rating DESC'\",\"  const params = { ...input, favorites: Number(input.favorites), free: Number(input.free), userId }\",\"  const prompts = db.prepare(`SELECT ${promptSelect},ROW_NUMBER() OVER(ORDER BY ${order}) AS rank FROM prompts p JOIN creators c ON c.id=p.creator_id WHERE ${where} ORDER BY ${order}`).all(params) as Prompt[]\",\"  const counts = db.prepare(`SELECT COUNT(*) total,SUM(price_cents=0) free,SUM(price_cents>0) paid,SUM(featured=1) featured,SUM(EXISTS(SELECT 1 FROM favorites f WHERE f.prompt_id=p.id AND f.user_id=?)) favorites FROM prompts p`).get(userId) as CatalogResult['counts']\",\"  const categories = db.prepare('SELECT category name,COUNT(*) count FROM prompts GROUP BY category ORDER BY count DESC,name').all() as CatalogResult['categories']\",\"  return { prompts, counts, categories }\",\"}\",\"\",\"export function getPrompt(db: PowerPromptDb, promptId: number, userId = 1) {\",\"  return db.prepare(`SELECT ${promptSelect},1 AS rank FROM prompts p JOIN creators c ON c.id=p.creator_id WHERE p.id=@promptId`).get({ promptId, userId }) as Prompt | undefined\",\"}\",\"\",\"export function toggleFavorite(db: PowerPromptDb, promptId: number, userId = 1) {\",\"  const exists = db.prepare('SELECT 1 FROM favorites WHERE user_id=? AND prompt_id=?').get(userId, promptId)\",\"  if (exists) db.prepare('DELETE FROM favorites WHERE user_id=? AND prompt_id=?').run(userId, promptId)\",\"  else db.prepare('INSERT INTO favorites(user_id,prompt_id) VALUES (?,?)').run(userId, promptId)\",\"  return { favorite: !exists }\",\"}\",\"\",\"export function setCartQuantity(db: PowerPromptDb, promptId: number, quantity: number, userId = 1) {\",\"  if (quantity === 0) db.prepare('DELETE FROM cart_items WHERE user_id=? AND prompt_id=?').run(userId, promptId)\",\"  else db.prepare('INSERT INTO cart_items(user_id,prompt_id,quantity) VALUES (?,?,?) ON CONFLICT(user_id,prompt_id) DO UPDATE SET quantity=excluded.quantity').run(userId, promptId, quantity)\",\"  return getCart(db, userId)\",\"}\",\"\",\"export function getCart(db: PowerPromptDb, userId = 1): CartSummary {\",\"  const items = db.prepare(`SELECT ${promptSelect},ci.quantity,(p.price_cents*ci.quantity)/100.0 lineTotal,1 rank FROM cart_items ci JOIN prompts p ON p.id=ci.prompt_id JOIN creators c ON c.id=p.creator_id WHERE ci.user_id=@userId ORDER BY ci.rowid`).all({ userId }) as CartSummary['items']\",\"  const totals = db.prepare(`SELECT COALESCE(SUM(p.price_cents*ci.quantity),0) subtotal,COALESCE(ROUND(SUM(p.price_cents*ci.quantity)*0.08),0) fee,COALESCE(SUM(p.price_cents*ci.quantity)+ROUND(SUM(p.price_cents*ci.quantity)*0.08),0) total,COALESCE(SUM(ci.quantity),0) itemCount FROM cart_items ci JOIN prompts p ON p.id=ci.prompt_id WHERE ci.user_id=?`).get(userId) as { subtotal:number; fee:number; total:number; itemCount:number }\",\"  return { items, itemCount: totals.itemCount, subtotal: totals.subtotal / 100, fee: totals.fee / 100, total: totals.total / 100 }\",\"}\",\"\",\"export function checkout(db: PowerPromptDb, userId = 1) {\",\"  return db.transaction(() => {\",\"    const cart = getCart(db, userId)\",\"    if (!cart.itemCount) throw new Error('Cart is empty')\",\"    const now = new Date().toISOString().slice(0, 10)\",\"    const order = db.prepare('INSERT INTO orders(user_id,status,subtotal_cents,fee_cents,total_cents,created_at) VALUES (?,\\\\'paid\\\\',?,?,?,?)').run(userId, Math.round(cart.subtotal*100), Math.round(cart.fee*100), Math.round(cart.total*100), now)\",\"    const add = db.prepare('INSERT INTO order_items(order_id,prompt_id,creator_id,quantity,unit_price_cents) VALUES (?,?,?,?,?)')\",\"    cart.items.forEach((item) => add.run(order.lastInsertRowid, item.id, item.creatorId, item.quantity, Math.round(item.price*100)))\",\"    db.prepare('DELETE FROM cart_items WHERE user_id=?').run(userId)\",\"    return { orderId: Number(order.lastInsertRowid), total: cart.total }\",\"  })()\",\"}\",\"\",\"export function getAnalytics(db: PowerPromptDb, creatorId = 2): Analytics {\",\"  const creator = db.prepare(`SELECT c.name,COALESCE(SUM(oi.quantity*oi.unit_price_cents),0)/100.0 revenue,COUNT(DISTINCT oi.order_id) orders,COALESCE(SUM(p.views),0) views,ROUND(100.0*COUNT(DISTINCT oi.order_id)/NULLIF(SUM(p.views),0),2) conversionRate,COALESCE(ROUND(SUM(oi.quantity*oi.unit_price_cents)*1.0/NULLIF(COUNT(DISTINCT oi.order_id),0))/100.0,0) averageOrderValue FROM creators c LEFT JOIN prompts p ON p.creator_id=c.id LEFT JOIN order_items oi ON oi.prompt_id=p.id AND oi.creator_id=c.id WHERE c.id=? GROUP BY c.id`).get(creatorId) as Analytics['creator']\",\"  const categories = db.prepare(`SELECT p.category,ROUND(SUM(oi.quantity*oi.unit_price_cents))/100.0 revenue,SUM(oi.quantity) units FROM order_items oi JOIN prompts p ON p.id=oi.prompt_id GROUP BY p.category ORDER BY revenue DESC`).all() as Analytics['categories'