: tests/db.test.ts\n+import { afterEach, beforeEach, describe, expect, it } from 'vitest'\n+import { createDatabase, type PowerPromptDb } from '../src/server/db'\n+import { getAnalytics, getCart, getCatalog, setCartQuantity } from '../src/server/queries'\n+\n+describe('database calculations', () => {\n+  let db: PowerPromptDb\n+  beforeEach(() => { db=createDatabase() })\n+  afterEach(() => db.close())\n+  it('ranks featured prompts and returns database filter counts', () => {\n+    const result=getCatalog(db,{model:'all',category:'all',sort:'featured',search:'',favorites:false,free:false})\n+    expect(result.prompts).toHaveLength(22); expect(result.prompts[0].rank).toBe(1); expect(result.prompts[0].featured).toBe(1)\n+    expect(result.counts).toMatchObject({total:22,free:1,paid:21})\n+  })\n+  it('calculates cart subtotal, fee, and total in SQL', () => {\n+    setCartQuantity(db,207,2); setCartQuantity(db,160,1)\n+    expect(getCart(db)).toMatchObject({itemCount:3,subtotal:36,fee:2.88,total:38.88})\n+  })\n+  it('summarizes creator and category revenue from order rows', () => {\n+    const data=getAnalytics(db,2)\n+    expect(data.creator.revenue).toBe(44); expect(data.creator.orders).toBe(2); expect(data.creator.averageOrderValue).toBe(22)\n+    expect(data.categories[0].revenue).toBeGreaterThan(0); expect(data.daily).toHaveLength(3)\n+  })\n+})\n*** Add File: tests/api.test.ts\n+import { afterEach, beforeEach, describe, expect, it } from 'vitest'\n+import { catalogInput } from '../src/contracts'\n+import { createDatabase, type PowerPromptDb } from '../src/server/db'\n+import { checkout, getCart, getCatalog, setCartQuantity, toggleFavorite } from '../src/server/queries'\n+\n+describe('backend contracts and flows', () => {\n+  let db: PowerPromptDb\n+  beforeEach(() => { db=createDatabase() }); afterEach(() => db.close())\n+  it('validates and applies API catalog filters', () => {\n+    const input=catalogInput.parse({model:'Flux',sort:'popular'})\n+    const result=getCatalog(db,input)\n+    expect(result.prompts.length).toBeGreaterThan(3); expect(result.prompts.every((prompt)=>prompt.model==='Flux')).toBe(true)\n+  })\n+  it('persists favorite mutations', () => {\n+    expect(toggleFavorite(db,233).favorite).toBe(true)\n+    expect(getCatalog(db,{model:'all',category:'all',sort:'featured',search:'',favorites:true,free:false}).prompts.map((p)=>p.id)).toContain(233)\n+  })\n+  it('persists checkout and clears the cart atomically', () => {\n+    setCartQuantity(db,301,1); const order=checkout(db)\n+    expect(order.orderId).toBe(4); expect(order.total).toBe(15.12); expect(getCart(db).itemCount).toBe(0)\n+    expect(db.prepare('SELECT status FROM orders WHERE id=?').get(order.orderId)).toEqual({status:'paid'})\n+  })\n+})\n*** Add File: playwright.config.ts\n+import { defineConfig, devices } from '@playwright/test'\n+export default defineConfig({ testDir:'./tests/e2e', timeout:30_000, retries:0, reporter:'line', use:{baseURL:'http://127.0.0.1:4173',trace:'retain-on-failure'}, webServer:{command:'npm run dev -- --host 127.0.0.1',url:'http://127.0.0.1:4173',reuseExistingServer:false,timeout:120_000}, projects:[{name:'desktop',use:{...devices['Desktop Chrome']}},{name:'mobile',use:{...devices['iPhone 13']}}] })\n*** Add File: tests/e2e/storefront.spec.ts\n+import { expect, test } from '@playwright/test'\n+test('filters, previews, favorites, and cart checkout', async ({page}) => {\n+  await page.goto('/'); await expect(page.getByText('POWERPROMPT').first()).toBeVisible(); await expect(page.getByTestId('prompt-card')).toHaveCount(22)\n+  await page.getByRole('button',{name:'Flux'}).click(); await expect(page.getByTestId('prompt-card')).toHaveCount(6)\n+  await page.getByRole('link',{name:/Preview Editorial Photo Grade/}).click(); await expect(page.getByRole('heading',{name:'Editorial Photo Grade'})).toBeVisible()\n+  await page.getByRole('button',{name:/Add to Cart/}).click(); await page.getByRole('link',{name:/Cart, 1 items/}).last().click(); await expect(page.getByRole('heading',{name:/Cart/})).toBeVisible()\n+  await page.getByRole('button',{name:'Complete checkout'}).click(); await expect(page.getByRole('heading',{name:'Your prompt stack is ready.'})).toBeVisible()\n+})\n+test('creator analytics and API are server-backed', async ({page,request}) => {\n+  const response=await request.get('/api/prompts?model=Claude'); expect(response.ok()).toBeTruthy(); const body=await response.json(); expect(body.prompts.every((p:{model:string})=>p.model==='Claude')).toBeTruthy()\n+  await page.goto('/creator'); await expect(page.getByRole('heading',{name:'Field & Co.'})).toBeVisible(); await expect(page.getByText('Revenue trend')).toBeVisible()\n+})\n*** End Patch","command_type":"apply_patch","id":"runtime-18c107eee74c10dc.tool.command_run:call_Xb9IVqTcYjjXasN65fPcIZDF:12","provider_tool_call_id":"call_Xb9IVqTcYjjXasN65fPcIZDF","status":"completed","step":1,"type":"file_change"},"type":"item.completed"}
